import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.2af478d7.js";const u=JSON.parse('{"title":"Routes and controllers","description":"","frontmatter":{},"headers":[],"relativePath":"routes-and-controllers.md","filePath":"routes-and-controllers.md"}'),d={name:"routes-and-controllers.md"};function r(i,e,n,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="routes-and-controllers" tabindex="-1">Routes and controllers <a class="header-anchor" href="#routes-and-controllers" aria-label="Permalink to &quot;Routes and controllers&quot;">​</a></h1><p>The package registers the routes your descriptor implies, plus a webhook, optional search routes and a documentation route. This page lists every route name, the controllers behind them and how to take over registration.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Declare at least one content type, as in the <a href="./quick-start">Quick start</a>. With none, the package registers no content, webhook or search routes.</p><h2 id="route-names" tabindex="-1">Route names <a class="header-anchor" href="#route-names" aria-label="Permalink to &quot;Route names&quot;">​</a></h2><p>List the registered routes with <code>php artisan route:list --name=talk</code>. These are all the names the package can register:</p><table tabindex="0"><thead><tr><th>Name</th><th>Method and URI</th><th>Registered when</th></tr></thead><tbody><tr><td><code>{key}.index</code></td><td><code>GET {listing_path}</code></td><td>A primary or facet type sets <code>listing_path</code></td></tr><tr><td><code>{key}</code></td><td><code>GET {url_prefix}/{alias}</code></td><td>A primary or facet type exists. With an empty <code>url_prefix</code> the URI is <code>/{alias}</code>.</td></tr><tr><td><code>page.{slug}</code></td><td><code>GET</code> the URL in the page type&#39;s <code>routes</code> map</td><td>A page type declares <code>routes</code></td></tr><tr><td><code>hooks.drupal</code></td><td><code>POST {webhook.path}</code></td><td>Always, for the default Source</td></tr><tr><td><code>hooks.drupal.source</code></td><td><code>POST {webhook.path}/{source}</code></td><td>Always, for any Source</td></tr><tr><td><code>search</code></td><td><code>GET {prefix}/search</code></td><td><code>search.enabled</code> is true</td></tr><tr><td><code>search.suggest</code></td><td><code>GET {prefix}/search/suggest</code></td><td><code>search.enabled</code> is true</td></tr><tr><td><code>drupal-backend-docs.docs</code></td><td><code>GET /backend-docs/{path?}</code></td><td>Registered by <code>proteo/drupal-backend-docs</code>, not by this package. Answers 404 in production unless <code>drupal-backend-docs.enabled</code> is <code>true</code>.</td></tr></tbody></table><p><code>{key}</code> is the content type key, so a <code>talk</code> type gives the routes <code>talk.index</code> and <code>talk</code>. Use them with <code>route(&#39;talk&#39;, $alias)</code>.</p><h2 id="controllers-and-view-data" tabindex="-1">Controllers and view data <a class="header-anchor" href="#controllers-and-view-data" aria-label="Permalink to &quot;Controllers and view data&quot;">​</a></h2><p>Each route is served by a plain controller. It picks the first view that exists in a <a href="./views-and-overrides">chain</a> and passes the data below.</p><table tabindex="0"><thead><tr><th>Route</th><th>Controller</th><th>Fetches</th><th>View data</th></tr></thead><tbody><tr><td><code>{key}</code></td><td><code>ContentItemController</code></td><td>The item, through <code>ContentFetcher::item()</code></td><td><code>{key}</code>, <code>entity</code>, <code>type</code>, <code>seo</code></td></tr><tr><td><code>{key}.index</code></td><td><code>ContentListingController</code></td><td>Nothing. The <code>drupal::listing</code> Livewire component fetches each page.</td><td><code>type</code></td></tr><tr><td><code>page.{slug}</code></td><td><code>ContentPageController</code></td><td>The page, with the slug as the alias</td><td><code>{key}</code>, <code>entity</code>, <code>type</code>, <code>seo</code></td></tr><tr><td><code>search</code></td><td><code>SearchPageController</code></td><td>Nothing. The <code>drupal::search</code> component does.</td><td>none</td></tr><tr><td><code>search.suggest</code></td><td><code>SearchSuggestionsController</code></td><td>Suggestions for the query <code>q</code></td><td>JSON list of <code>type</code>, <code>title</code>, <code>url</code>, <code>subtitle</code></td></tr><tr><td><code>hooks.drupal</code>, <code>hooks.drupal.source</code></td><td><code>DrupalWebhookController</code></td><td>Nothing. It flushes the Source.</td><td>Empty <code>202</code> answer</td></tr></tbody></table><p>The webhook routes sit outside the <code>web</code> middleware group, so they have no session and no CSRF check. See <a href="./webhook-and-cache-flushing">Webhook and cache flushing</a>.</p><h2 id="prefix-middleware-and-alias-pattern" tabindex="-1">Prefix, middleware and alias pattern <a class="header-anchor" href="#prefix-middleware-and-alias-pattern" aria-label="Permalink to &quot;Prefix, middleware and alias pattern&quot;">​</a></h2><p>Three <code>routes</code> settings shape every content route, the search page and the suggestions:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Effect</th></tr></thead><tbody><tr><td><code>routes.prefix</code></td><td><code>&#39;&#39;</code></td><td>URI prefix, for example <code>shop</code>. The webhook ignores it.</td></tr><tr><td><code>routes.middleware</code></td><td><code>[&#39;web&#39;]</code></td><td>Middleware of the routes.</td></tr><tr><td><code>routes.alias_pattern</code></td><td><code>[a-z0-9-]{1,128}</code></td><td>Allowed shape of <code>{alias}</code>. Other URLs are a plain 404 and never reach Drupal.</td></tr></tbody></table><p>The package adds the rate limiter: <code>throttle:content</code> for content and the search page, <code>throttle:search-suggest</code> for suggestions. See the <a href="./configuration-reference#routes">Configuration reference</a>.</p><h2 id="pick-one-automatic-routes-or-route-drupalcontent" tabindex="-1">Pick one: automatic routes or <code>Route::drupalContent()</code> <a class="header-anchor" href="#pick-one-automatic-routes-or-route-drupalcontent" aria-label="Permalink to &quot;Pick one: automatic routes or \`Route::drupalContent()\`&quot;">​</a></h2><p>By default the package registers content routes itself. To place them yourself, for example in your own middleware group or order, turn that off and call the macro:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;routes&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;auto&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Illuminate\\Support\\Facades\\Route</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Route</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">middleware</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;throttle:content&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    Route</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">drupalContent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;talk&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;speaker&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;topic&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;track&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;page&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p><code>Route::drupalContent()</code> with no arguments registers every primary, facet and page type. With keys, it registers only those. Use one approach, not both: with <code>routes.auto</code> on, the macro call is redundant, and it gives you no control over order or middleware.</p><p>Webhook and search routes are always registered by the package. Only content routes follow <code>routes.auto</code>.</p><p>A type with an empty <code>url_prefix</code> serves items at <code>/{alias}</code>, which matches any single segment that fits <code>alias_pattern</code>. Register your own fixed routes first, or place the macro call last.</p><h2 id="route-caching" tabindex="-1">Route caching <a class="header-anchor" href="#route-caching" aria-label="Permalink to &quot;Route caching&quot;">​</a></h2><p><code>php artisan route:cache</code> works. The package skips its own registration when routes are cached, and the documentation route is part of the cache. Run the cache command after the descriptor is final.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>A failed fetch becomes a 404, 502 or 503 response. The controllers render your <code>errors.{status}</code> view first and fall back to <code>drupal::error</code>. See <a href="./architecture#when-drupal-fails">Architecture</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Customise the pages in <a href="./views-and-overrides">Views and overrides</a>.</li><li>Put the search page behind your layout in <a href="./search-setup">Search setup</a>.</li><li>Look up every routing option in the <a href="./configuration-reference">Configuration reference</a>.</li></ul>`,29)])])}const k=t(d,[["render",r]]);export{u as __pageData,k as default};
